 alter table addons add constraint addons_category_check CHECK ((category = ANY (ARRAY['food'::text, 'activity'::text, 'facility'::text, 'transport'::text, 'other'::text])));
alter table addons add constraint addons_pkey PRIMARY KEY (id);
alter table addons add constraint addons_property_id_fkey FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE CASCADE;
alter table addons add constraint addons_unit_check CHECK ((unit = ANY (ARRAY['per_person_day'::text, 'per_person'::text, 'per_group'::text, 'per_day'::text, 'per_stay'::text])));
alter table addons add constraint addons_variants_check CHECK ((jsonb_typeof(variants) = 'array'::text));
alter table agents add constraint agents_default_commission_type_check CHECK ((default_commission_type = ANY (ARRAY['percentage'::text, 'flat'::text])));
alter table agents add constraint agents_pkey PRIMARY KEY (id);
alter table agents add constraint agents_property_id_fkey FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE CASCADE;
alter table availability add constraint availability_pkey PRIMARY KEY (room_id, date);
alter table availability add constraint availability_room_id_fkey FOREIGN KEY (room_id) REFERENCES rooms(id) ON DELETE CASCADE;
alter table booking_charges add constraint booking_charges_booking_id_fkey FOREIGN KEY (booking_id) REFERENCES bookings(id) ON DELETE CASCADE;
alter table booking_charges add constraint booking_charges_group_id_fkey FOREIGN KEY (group_id) REFERENCES booking_groups(id) ON DELETE CASCADE;
alter table booking_charges add constraint booking_charges_pkey PRIMARY KEY (id);
alter table booking_groups add constraint booking_groups_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL;
alter table booking_groups add constraint booking_groups_pkey PRIMARY KEY (id);
alter table booking_groups add constraint booking_groups_property_id_fkey FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE CASCADE;
alter table booking_groups add constraint booking_groups_source_check CHECK ((source = ANY (ARRAY['direct'::text, 'agent'::text, 'walk_in'::text])));
alter table bookings add constraint bookings_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL;
alter table bookings add constraint bookings_group_id_fkey FOREIGN KEY (group_id) REFERENCES booking_groups(id) ON DELETE SET NULL;
alter table bookings add constraint bookings_no_overlap EXCLUDE USING gist (room_id WITH =, daterange(check_in, check_out, '[)'::text) WITH &&) WHERE ((status <> 'cancelled'::text));
alter table bookings add constraint bookings_pkey PRIMARY KEY (id);
alter table bookings add constraint bookings_property_id_fkey FOREIGN KEY (property_id) REFERENCES properties(id);
alter table bookings add constraint bookings_room_id_fkey FOREIGN KEY (room_id) REFERENCES rooms(id) ON DELETE SET NULL;
alter table bookings add constraint bookings_source_check CHECK ((source = ANY (ARRAY['direct'::text, 'agent'::text, 'walk_in'::text])));
alter table client_errors add constraint client_errors_category_len CHECK ((char_length(category) <= 20));
alter table client_errors add constraint client_errors_ctx_len CHECK (((context IS NULL) OR (char_length((context)::text) <= 1500)));
alter table client_errors add constraint client_errors_host_len CHECK (((hostname IS NULL) OR (char_length(hostname) <= 120)));
alter table client_errors add constraint client_errors_message_len CHECK (((char_length(message) >= 1) AND (char_length(message) <= 600)));
alter table client_errors add constraint client_errors_pkey PRIMARY KEY (id);
alter table client_errors add constraint client_errors_source_len CHECK ((char_length(source) <= 30));
alter table client_errors add constraint client_errors_stack_len CHECK (((stack IS NULL) OR (char_length(stack) <= 2500)));
alter table client_errors add constraint client_errors_ua_len CHECK (((user_agent IS NULL) OR (char_length(user_agent) <= 300)));
alter table client_errors add constraint client_errors_url_len CHECK (((url IS NULL) OR (char_length(url) <= 300)));
alter table client_errors add constraint client_errors_ver_len CHECK (((app_version IS NULL) OR (char_length(app_version) <= 40)));
alter table invite_tokens add constraint invite_tokens_pkey PRIMARY KEY (id);
alter table invite_tokens add constraint invite_tokens_property_id_fkey FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE CASCADE;
alter table invite_tokens add constraint invite_tokens_token_key UNIQUE (token);
alter table leads add constraint leads_name_len CHECK (((char_length(name) >= 1) AND (char_length(name) <= 120))) NOT VALID;
alter table leads add constraint leads_phone_len CHECK (((char_length(phone) >= 5) AND (char_length(phone) <= 30))) NOT VALID;
alter table leads add constraint leads_pkey PRIMARY KEY (id);
alter table leads add constraint leads_prop_len CHECK (((property_name IS NULL) OR (char_length(property_name) <= 200))) NOT VALID;
alter table leads add constraint leads_tier_len CHECK (((tier IS NULL) OR (char_length(tier) <= 40))) NOT VALID;
alter table packages add constraint packages_included_check CHECK ((jsonb_typeof(included) = 'array'::text));
alter table packages add constraint packages_pkey PRIMARY KEY (id);
alter table packages add constraint packages_property_id_fkey FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE CASCADE;
alter table packages add constraint packages_unit_check CHECK ((unit = ANY (ARRAY['per_person_day'::text, 'per_person'::text, 'per_group'::text, 'per_day'::text, 'per_stay'::text])));
alter table packages add constraint packages_variants_check CHECK ((jsonb_typeof(variants) = 'array'::text));
alter table price_seasons add constraint price_seasons_dates_ok CHECK ((recurs_yearly OR (end_date >= start_date)));
alter table price_seasons add constraint price_seasons_pkey PRIMARY KEY (id);
alter table price_seasons add constraint price_seasons_property_id_fkey FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE CASCADE;
alter table properties add constraint properties_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES auth.users(id);
alter table properties add constraint properties_pending_hold_hours_check CHECK (((pending_hold_hours > 0) AND (pending_hold_hours <= 168)));
alter table properties add constraint properties_pkey PRIMARY KEY (id);
alter table properties add constraint properties_subdomain_key UNIQUE (subdomain);
alter table properties add constraint properties_subscription_status_check CHECK ((subscription_status = ANY (ARRAY['pending_setup'::text, 'active'::text, 'suspended'::text, 'trial'::text])));
alter table properties add constraint properties_subscription_tier_check CHECK ((subscription_tier = ANY (ARRAY['small'::text, 'large'::text])));
alter table quotes add constraint quotes_converted_booking_id_fkey FOREIGN KEY (converted_booking_id) REFERENCES bookings(id) ON DELETE SET NULL;
alter table quotes add constraint quotes_dates_ok CHECK ((check_out >= check_in));
alter table quotes add constraint quotes_pkey PRIMARY KEY (id);
alter table quotes add constraint quotes_property_id_fkey FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE CASCADE;
alter table quotes add constraint quotes_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'sent'::text, 'accepted'::text, 'lost'::text])));
alter table room_ical_feeds add constraint room_ical_feeds_name_len CHECK (((char_length(name) >= 1) AND (char_length(name) <= 60)));
alter table room_ical_feeds add constraint room_ical_feeds_pkey PRIMARY KEY (id);
alter table room_ical_feeds add constraint room_ical_feeds_property_id_fkey FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE CASCADE;
alter table room_ical_feeds add constraint room_ical_feeds_room_id_fkey FOREIGN KEY (room_id) REFERENCES rooms(id) ON DELETE CASCADE;
alter table room_ical_feeds add constraint room_ical_feeds_status_ok CHECK (((last_status IS NULL) OR (last_status = ANY (ARRAY['ok'::text, 'error'::text]))));
alter table room_ical_feeds add constraint room_ical_feeds_url_ok CHECK (((url ~* '^(https|webcal)://'::text) AND (char_length(url) <= 2000)));
alter table room_rates add constraint room_rates_dates_ok CHECK ((end_date >= start_date));
alter table room_rates add constraint room_rates_kind_ok CHECK ((kind = ANY (ARRAY['fixed'::text, 'percent'::text])));
alter table room_rates add constraint room_rates_label_len CHECK ((char_length(label) <= 60));
alter table room_rates add constraint room_rates_pkey PRIMARY KEY (id);
alter table room_rates add constraint room_rates_property_id_fkey FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE CASCADE;
alter table room_rates add constraint room_rates_room_id_fkey FOREIGN KEY (room_id) REFERENCES rooms(id) ON DELETE CASCADE;
alter table room_rates add constraint room_rates_span_ok CHECK (((end_date - start_date) <= 400));
alter table room_rates add constraint room_rates_value_ok CHECK ((((kind = 'fixed'::text) AND (value > (0)::numeric) AND (value <= (1000000)::numeric) AND (value = round(value))) OR ((kind = 'percent'::text) AND (value > ('-90'::integer)::numeric) AND (value <= (500)::numeric) AND (value = round(value)))));
alter table rooms add constraint rooms_pkey PRIMARY KEY (id);
alter table rooms add constraint rooms_property_id_fkey FOREIGN KEY (property_id) REFERENCES properties(id);

CREATE INDEX addons_property_idx ON public.addons USING btree (property_id);
CREATE INDEX idx_agents_property_id ON public.agents USING btree (property_id);
CREATE INDEX idx_availability_room_date ON public.availability USING btree (room_id, date);
CREATE INDEX booking_charges_group_id_idx ON public.booking_charges USING btree (group_id) WHERE (group_id IS NOT NULL);
CREATE INDEX idx_booking_charges_booking_id ON public.booking_charges USING btree (booking_id);
CREATE INDEX booking_groups_property_checkin_idx ON public.booking_groups USING btree (property_id, check_in DESC);
CREATE INDEX idx_booking_groups_agent_id ON public.booking_groups USING btree (agent_id);
CREATE INDEX idx_booking_groups_pending_hold ON public.booking_groups USING btree (hold_expires_at) WHERE ((status = 'pending'::text) AND (hold_expires_at IS NOT NULL));
CREATE INDEX bookings_group_id_idx ON public.bookings USING btree (group_id) WHERE (group_id IS NOT NULL);
CREATE INDEX idx_bookings_agent_id ON public.bookings USING btree (agent_id);
CREATE INDEX idx_bookings_check_in ON public.bookings USING btree (check_in);
CREATE INDEX idx_bookings_guest_phone ON public.bookings USING btree (guest_phone);
CREATE INDEX idx_bookings_pending_hold ON public.bookings USING btree (hold_expires_at) WHERE ((status = 'pending'::text) AND (hold_expires_at IS NOT NULL));
CREATE INDEX idx_bookings_property ON public.bookings USING btree (property_id);
CREATE INDEX idx_bookings_room ON public.bookings USING btree (room_id);
CREATE INDEX client_errors_created_at_idx ON public.client_errors USING btree (created_at DESC);
CREATE INDEX packages_property_idx ON public.packages USING btree (property_id);
CREATE INDEX price_seasons_property_idx ON public.price_seasons USING btree (property_id);
CREATE INDEX idx_properties_owner ON public.properties USING btree (owner_id);
CREATE INDEX idx_properties_subdomain ON public.properties USING btree (subdomain);
CREATE INDEX quotes_property_created_idx ON public.quotes USING btree (property_id, created_at DESC);
CREATE INDEX room_ical_feeds_property_idx ON public.room_ical_feeds USING btree (property_id);
CREATE INDEX room_ical_feeds_room_idx ON public.room_ical_feeds USING btree (room_id);
CREATE INDEX room_rates_property_idx ON public.room_rates USING btree (property_id, start_date);
CREATE INDEX room_rates_room_idx ON public.room_rates USING btree (room_id);
CREATE INDEX idx_rooms_property ON public.rooms USING btree (property_id);
